/* Development PWA: generated by scripts/package-development.py. No user data here. */
'use strict';
const BUILD = __BUILD__;
const CORE = __CORE__;
const OPTIONAL = __OPTIONAL__;
const PREFIX = 'almogaver-public-' + BUILD + '-';
const NAMES = {core:PREFIX+'core', recovery:PREFIX+'recovery', optional:PREFIX+'optional'};
const absolute = path => new URL(path, self.registration.scope).href;
const entries = new Map([...CORE, ...OPTIONAL].map(x => [absolute(x.url), x]));
const indexURL = absolute('index.html');
const rootURL = self.registration.scope;
const readyURL = absolute('__public_install_complete__');
let firstInstall = false;
const sha = async buffer => [...new Uint8Array(await crypto.subtle.digest('SHA-256', buffer))].map(x=>x.toString(16).padStart(2,'0')).join('');

async function verified(entry) {
  // Credentials are never sent when filling Cache Storage. No arbitrary fetch response is cached.
  const response = await fetch(absolute(entry.source?.url || entry.url), {credentials:'omit', cache:'no-store', redirect:'error'});
  const cc = response.headers.get('cache-control') || '';
  const vary = response.headers.get('vary') || '';
  if (!response.ok || response.status !== 200 || response.type === 'opaque' ||
      /private/i.test(cc) || /(?:\*|cookie|authorization)/i.test(vary) ||
      response.headers.has('www-authenticate') || response.headers.has('set-cookie') ||
      // Existing 7.1.1 headers mark the public HTML shell no-store. Only these pinned documents
      // have an explicit offline exception; their exact public bytes must match at installation.
      (/no-store/i.test(cc) && entry.kind !== 'document')) throw Error('Non-public resource: '+entry.url);
  let bytes = await response.clone().arrayBuffer();
  if (entry.source) {
    if (entry.kind !== 'document' || !/^application\/json(?:\s*;|$)/i.test(response.headers.get('content-type') || '') ||
        await sha(bytes) !== entry.source.sha256) throw Error('Incompatible public transport: '+entry.url);
    const payload = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes));
    if (payload.version !== 1 || payload.document !== entry.url || typeof payload.base64 !== 'string')
      throw Error('Invalid public document transport: '+entry.url);
    bytes = Uint8Array.from(atob(payload.base64), char=>char.charCodeAt(0)).buffer;
  }
  if (await sha(bytes) !== entry.sha256) throw Error('Incompatible resource: '+entry.url);
  if (entry.source) {
    // Preserve security headers; encoding/length/disposition describe the JSON transport only.
    const headers = new Headers(response.headers);
    for (const name of ['content-encoding','content-length','content-disposition','etag']) headers.delete(name);
    headers.set('content-type', 'text/html; charset=utf-8');
    headers.set('cache-control', 'no-store');
    return new Response(bytes, {status:200, headers});
  }
  return response;
}

self.addEventListener('install', event => {
  firstInstall = !self.registration.active;
  event.waitUntil((async()=>{
    try {
      // A different build never writes another build's caches. Installation succeeds as a unit:
      // only a fully installed worker can activate; failed candidates delete only their own caches.
      for (const entry of CORE) {
        const cache = await caches.open(NAMES[entry.bucket]);
        await cache.put(absolute(entry.url), await verified(entry));
      }
      await (await caches.open(NAMES.core)).put(readyURL, new Response(JSON.stringify({build:BUILD,firstInstall})));
    } catch (error) {
      await Promise.all(Object.values(NAMES).map(name=>caches.delete(name)));
      throw error;
    }
  })());
  // Deliberately no skipWaiting: all existing training/recovery windows must close.
});

self.addEventListener('activate', event => {
  event.waitUntil((async()=>{
    const complete = await (await caches.open(NAMES.core)).match(readyURL);
    const metadata = complete && await complete.json();
    if (metadata?.build !== BUILD) throw Error('Incomplete public installation');
    // Retain old public caches for rollback/old windows. Never touch IDB or localStorage.
    // Claim is safe only for the first installation; upgrades never claim running documents.
    if (metadata.firstInstall) await self.clients.claim();
  })());
});

function publicEntry(request) {
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin ||
      request.headers.has('authorization') || request.headers.has('range')) return null;
  // Root and index are an explicit document alias, only without query parameters.
  // Every other URL (including query strings) must match an exact manifest entry.
  const key = request.url === rootURL ? indexURL : request.url;
  return entries.get(key) || null;
}

self.addEventListener('fetch', event => {
  const entry = publicEntry(event.request);
  if (!entry) return; // Network only: APIs, payments, sessions, exports, unknown URLs, non-GET.
  event.respondWith((async()=>{
    const cache = await caches.open(NAMES[entry.bucket]);
    const key = absolute(entry.url);
    const cached = await cache.match(key); // Exact URL; never ignoreSearch.
    if (cached) return cached;
    // Repair an evicted entry only with exact bytes from this same public cohort.
    try {
      const response = await verified(entry);
      await cache.put(key, response.clone());
      return response;
    } catch (_) { return Response.error(); }
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'ALMOGAVER_PUBLIC_STATUS') event.ports[0]?.postMessage({build:BUILD,caches:NAMES,optional:OPTIONAL.map(x=>x.url),core:CORE.map(x=>x.url)});
  // No external message can force activation, delete data, or add cache URLs.
});
